import React, { forwardRef } from 'react';
import classNames from 'classnames';
import { renderChildren } from '@fiverr-private/ui_utils';
import { Container } from '@fiverr-private/layout_components';
import { Box } from '@fiverr-private/theme';
import { getValidationColor } from '../Checkbox/style';
import Input from '../Input';
import { filterProps } from '../shared/utils';
import { InputProps } from '../Input/types';
import { RadioProps } from './types';
import { circle, container, input, outline } from './styles.ve.css';

const Radio = forwardRef<HTMLInputElement, RadioProps>(
  (
    {
      children,
      disabled = false,
      isError = false,
      isSuccess = false,
      className,
      disableOutline,
      dataTrackTag = 'radio',
      dataTrackValue = '<checked>',
      ...rest
    },
    ref
  ) => {
    const { stylingProps, restProps } = filterProps(rest);
    const { color, borderColor } = getValidationColor({ disabled, isError, isSuccess });

    const inputProps: InputProps = {
      type: 'radio',
      disabled,
      width: 0,
      height: 0,
      className: input,
      opacity: '0',
      dataTrackTag,
      dataTrackValue,
      ...restProps,
    };

    return (
      <Box
        as="label"
        display="inlineFlex"
        direction="row"
        alignItems="center"
        color={color}
        boxSizing="borderBox"
        {...stylingProps}
        className={classNames(container, className)}
      >
        <Input role="radio" {...inputProps} ref={ref} />
        <Container
          as="span"
          display="inlineBlock"
          position="relative"
          width="20px"
          height="20px"
          flexShrink="0"
          alignSelf="flexStart"
          borderRadius="circle"
          marginRight="2"
          marginTop="px"
          borderWidth="sm"
          borderColor={borderColor}
          backgroundColor="background"
          cursor={disabled ? undefined : 'pointer'}
          userSelect="none"
          className={classNames(circle, { [outline]: !disableOutline })}
        ></Container>
        {renderChildren(children)}
      </Box>
    );
  }
);

Radio.displayName = 'Radio';

export default Radio;
