import React, { Children, forwardRef } from 'react';
import { Stack } from '@fiverr-private/layout_components';
import { renderChildren } from '@fiverr-private/ui_utils';
import { RadioGroupProps } from '../types';
import { filterProps } from '../../shared/utils';
import { useInputTrackValue } from '../../shared/useInputTrackValue';
import { useRadioGroup } from './hooks/useRadioGroup';

const RadioGroup = forwardRef<HTMLInputElement, RadioGroupProps>(
  (
    { children, direction = 'column', value, onChange, onBlur, dataTrackTag = 'radio_group', dataTrackValue, ...rest },
    ref
  ) => {
    const trackValue = useInputTrackValue({ dataTrackValue, value });
    const { stylingProps, restProps } = filterProps(rest);
    const { getExtendedProps } = useRadioGroup({ value, onChange });

    return (
      <Stack
        dataTrackTag={dataTrackTag}
        dataTrackValue={trackValue}
        onBlur={onBlur}
        gap="2"
        direction={direction}
        width="fit-content"
        {...stylingProps}
      >
        {Children.map(Children.toArray(children), (child) =>
          renderChildren(child, { ...restProps, ...getExtendedProps(child as React.ReactElement), ref })
        )}
      </Stack>
    );
  }
);

RadioGroup.displayName = 'RadioGroup';
export default RadioGroup;
